const results = await Promise.allSettled([
tools.exec_command({cmd:"rtk read /private/tmp/SPEC-RELEASE-CONVERGENCE-002.draft.json","max_output_tokens":10000}),
tools.exec_command({cmd:"rtk proxy rg --files /private/tmp/callisto-release-recovery/docs/requirements /private/tmp/callisto-release-recovery/docs/research /private/tmp/callisto-release-recovery/docs/findings /private/tmp/callisto-release-recovery/docs/architecture","max_output_tokens":6000}),
tools.exec_command({cmd:"rtk proxy rg --files crates/callisto-graph/src .github/actions .github/workflows","max_output_tokens":6000})
]); for(let i=0;i<results.length;i++) text({i,result:results[i]});

